import java.util.*;

class Solution {
    public int[] getOptimalSequence(int[] values, String state, int m) {
        int n = values.length;
        PriorityQueue<int[]> heap = new PriorityQueue<>((a, b) -> Integer.compare(b[0], a[0]));
        char[] st = state.toCharArray();
        for (int i = 0; i < n; i++) if (st[i] == '1') heap.offer(new int[] { values[i], i });
        int[] out = new int[m];
        int outIdx = 0;
        int nextZero = 0;
        while (outIdx < m && !heap.isEmpty()) {
            int[] top = heap.peek();
            out[outIdx++] = top[0];
            while (nextZero < n && st[nextZero] != '0') nextZero++;
            if (nextZero < n) {
                st[nextZero] = '1';
                heap.offer(new int[] { values[nextZero], nextZero });
                nextZero++;
            }
        }
        return out;
    }
}

#include <vector>
#include <queue>
#include <string>
using namespace std;

class Solution {
public:
    vector<int> getOptimalSequence(vector<int>& values, string state, int m) {
        int n = values.size();
        priority_queue<pair<int, int>> heap;
        for (int i = 0; i < n; i++) if (state[i] == '1') heap.push({values[i], i});
        vector<int> out;
        int nextZero = 0;
        while ((int) out.size() < m && !heap.empty()) {
            out.push_back(heap.top().first);
            while (nextZero < n && state[nextZero] != '0') nextZero++;
            if (nextZero < n) {
                state[nextZero] = '1';
                heap.push({values[nextZero], nextZero});
                nextZero++;
            }
        }
        return out;
    }
};
